using AcxiomCRM.Api.Contracts;
using AcxiomCRM.Api.Data;
using AcxiomCRM.Api.Models;
using AcxiomCRM.Api.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Api.Controllers;
[ApiController,Authorize,Route("api/users")]
public class UsersController(UserManager<AppUser> users,CrmDbContext db,Scope scope):ControllerBase {
 [HttpGet("assignable")]public async Task<IActionResult> Assignable(){var q=users.Users.Where(x=>x.IsActive);if(!scope.IsAdmin)q=scope.IsManager?q.Where(x=>scope.TeamId!=null&&x.TeamId==scope.TeamId):q.Where(x=>x.Id==scope.UserId);return Ok(await q.Select(x=>new{x.Id,x.Name,x.TeamId}).ToListAsync());}
 [HttpGet,Authorize(Roles="Admin")]public async Task<IActionResult> List(){var output=new List<object>();foreach(var u in await users.Users.OrderBy(x=>x.Name).ToListAsync())output.Add(new{u.Id,u.Name,u.Email,u.TeamId,u.IsActive,role=(await users.GetRolesAsync(u)).FirstOrDefault(),u.LockoutEnd});return Ok(new{items=output,total=output.Count});}
 [HttpPost,Authorize(Roles="Admin")]public async Task<IActionResult> Create(UserInput input){if(!new[]{"Admin","Manager","SalesExecutive"}.Contains(input.Role))return BadRequest(new{message="Invalid role."});if(string.IsNullOrEmpty(input.Password))return BadRequest(new{message="Initial password is required."});var u=new AppUser{Name=input.Name,Email=input.Email.ToLowerInvariant(),UserName=input.Email.ToLowerInvariant(),TeamId=input.TeamId,IsActive=input.IsActive,LockoutEnabled=true};var r=await users.CreateAsync(u,input.Password);if(!r.Succeeded)return BadRequest(new{message=string.Join(" ",r.Errors.Select(x=>x.Description))});r=await users.AddToRoleAsync(u,input.Role);if(!r.Succeeded){await users.DeleteAsync(u);return BadRequest(new{message="Role assignment failed."});}scope.Audit("Create","User",u.Id);await db.SaveChangesAsync();return Ok(new{u.Id});}
 [HttpPut("{id}"),Authorize(Roles="Admin")]public async Task<IActionResult> Update(string id,UserInput input){if(!new[]{"Admin","Manager","SalesExecutive"}.Contains(input.Role))return BadRequest(new{message="Invalid role."});if(!string.IsNullOrEmpty(input.Password))return BadRequest(new{message="Password cannot be changed through user editing."});var u=await users.FindByIdAsync(id);if(u==null)return NotFound();var roles=await users.GetRolesAsync(u);if(roles.Contains("Admin") && (!input.IsActive||input.Role!="Admin"))return BadRequest(new{message="Administrator demotion/deactivation requires a separate controlled process."});if(input.TeamId!=u.TeamId && (await db.Customers.AnyAsync(x=>x.OwnerId==id)||await db.Leads.AnyAsync(x=>x.OwnerId==id)||await db.Opportunities.AnyAsync(x=>x.OwnerId==id)||await db.FollowUps.AnyAsync(x=>x.OwnerId==id)||await db.Activities.AnyAsync(x=>x.OwnerId==id)))return Conflict(new{message="Reassign owned records before changing a user's team."});await using var tx=await db.Database.BeginTransactionAsync();u.Name=input.Name;u.TeamId=string.IsNullOrWhiteSpace(input.TeamId)?null:input.TeamId;u.IsActive=input.IsActive;var r=await users.SetEmailAsync(u,input.Email.Trim().ToLowerInvariant());if(!r.Succeeded)return BadRequest(new{message="Email update failed."});r=await users.SetUserNameAsync(u,u.Email!);if(!r.Succeeded)return BadRequest(new{message="Username update failed."});r=await users.UpdateAsync(u);if(!r.Succeeded)return BadRequest(new{message="User update failed."});r=await users.RemoveFromRolesAsync(u,roles);if(!r.Succeeded)return BadRequest(new{message="Role update failed."});r=await users.AddToRoleAsync(u,input.Role);if(!r.Succeeded)return BadRequest(new{message="Role update failed."});await users.UpdateSecurityStampAsync(u);scope.Audit("RoleOrStatusChange","User",u.Id);await db.SaveChangesAsync();await tx.CommitAsync();return NoContent();}
 [HttpPost("{id}/unlock"),Authorize(Roles="Admin")]public async Task<IActionResult> Unlock(string id){var u=await users.FindByIdAsync(id);if(u==null)return NotFound();await users.SetLockoutEndDateAsync(u,null);await users.ResetAccessFailedCountAsync(u);scope.Audit("Unlock","User",id);await db.SaveChangesAsync();return NoContent();}
 [HttpPost("{id}/reset-password"),Authorize(Roles="Admin")]public async Task<IActionResult> ResetPassword(string id,ResetPasswordInput input){var u=await users.FindByIdAsync(id);if(u==null)return NotFound();var token=await users.GeneratePasswordResetTokenAsync(u);var result=await users.ResetPasswordAsync(u,token,input.Password);if(!result.Succeeded)return BadRequest(new{message=string.Join(" ",result.Errors.Select(x=>x.Description))});scope.Audit("PasswordReset","User",id);await db.SaveChangesAsync();return NoContent();}
}
